import Foundation

/// The journey wire format (build plan §8.3, §8.4).
///
/// Mirrors `backend/app/journey/responses.py` and the `contracts/fixtures/turn_*`
/// files, which `ContractTests` decodes. A backend field rename fails the iOS
/// build rather than the demo.
///
/// **The app holds no business logic** (plan rule 10). These types carry what
/// the server decided; nothing here computes an EMI, decides whether a consent
/// may be given, or knows what step follows which.

// MARK: - Request

/// One customer turn.
struct TurnRequest: Encodable, Sendable {
    /// Generated by the client. A **retry must reuse the same id**, which is
    /// what makes a dropped response safe to re-send: the backend replays the
    /// stored answer instead of advancing the journey twice.
    let clientTurnId: UUID
    var expectedVersion: Int?
    let input: TurnInput
}

enum TurnInput: Encodable, Sendable {
    case text(String)
    case tap(JourneyAction)

    private enum CodingKeys: String, CodingKey {
        case type, text, action
    }

    func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        switch self {
        case .text(let value):
            try container.encode("text", forKey: .type)
            try container.encode(value, forKey: .text)
        case .tap(let action):
            try container.encode("tap", forKey: .type)
            try container.encode(action, forKey: .action)
        }
    }
}

/// Every tap the UI can send (§8.3 `Action`).
///
/// Encoded as a flat object with a `name` discriminator, matching the backend's
/// discriminated union. Modelled as an enum so an unhandled case is a compile
/// error rather than a 422 at demo time.
enum JourneyAction: Encodable, Sendable, Equatable {
    case setLanguage(Language)
    case amount(Int)
    case consents(digilocker: Bool, accountAggregator: Bool)
    case manualForm(ManualFormValues)
    case confirmDetails(shopAddress: String?, mobile: String?)
    case selectOffer(String)
    case quizAnswer(questionId: String, optionId: String)
    case insuranceAddon(Bool)
    case acceptTerms
    case repeatLast
    case didntUnderstand
    case requestHuman

    /// An action the backend composed and the app only relays (a quick-reply
    /// chip). Kept opaque so a new chip needs no app release: the server built
    /// it for this step, and the client has no reason to understand it.
    case relay(RawAction)

    private enum CodingKeys: String, CodingKey {
        case name, language, amount, grants, fields, edits, offerId, questionId, optionId, granted
    }

    private enum GrantKeys: String, CodingKey {
        case fetch_digilocker, fetch_account_aggregator  // swiftlint:disable:this identifier_name
    }

    private enum EditKeys: String, CodingKey {
        case shopAddress, mobile
    }

    func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)

        switch self {
        case .setLanguage(let language):
            try container.encode("set_language", forKey: .name)
            try container.encode(language, forKey: .language)

        case .amount(let value):
            try container.encode("amount", forKey: .name)
            try container.encode(value, forKey: .amount)

        case .consents(let digilocker, let aggregator):
            try container.encode("consents", forKey: .name)
            var grants = container.nestedContainer(keyedBy: GrantKeys.self, forKey: .grants)
            try grants.encode(digilocker, forKey: .fetch_digilocker)
            try grants.encode(aggregator, forKey: .fetch_account_aggregator)

        case .manualForm(let values):
            try container.encode("manual_form", forKey: .name)
            try container.encode(values, forKey: .fields)

        case .confirmDetails(let address, let mobile):
            try container.encode("confirm_details", forKey: .name)
            // Omitted entirely when nothing was edited: the backend's model is
            // `extra="forbid"`, and sending `{"edits": null}` is noise.
            if address != nil || mobile != nil {
                var edits = container.nestedContainer(keyedBy: EditKeys.self, forKey: .edits)
                try edits.encodeIfPresent(address, forKey: .shopAddress)
                try edits.encodeIfPresent(mobile, forKey: .mobile)
            }

        case .selectOffer(let offerId):
            try container.encode("select_offer", forKey: .name)
            try container.encode(offerId, forKey: .offerId)

        case .quizAnswer(let questionId, let optionId):
            try container.encode("quiz_answer", forKey: .name)
            try container.encode(questionId, forKey: .questionId)
            try container.encode(optionId, forKey: .optionId)

        case .insuranceAddon(let granted):
            try container.encode("insurance_addon", forKey: .name)
            try container.encode(granted, forKey: .granted)

        case .acceptTerms:
            try container.encode("accept_terms", forKey: .name)
        case .repeatLast:
            try container.encode("repeat", forKey: .name)
        case .didntUnderstand:
            try container.encode("didnt_understand", forKey: .name)
        case .requestHuman:
            try container.encode("request_human", forKey: .name)

        case .relay(let raw):
            // Encoded into the same container, so the relayed object *is* the
            // action rather than being nested inside one.
            try raw.encode(to: encoder)
        }
    }
}

struct ManualFormValues: Codable, Sendable, Equatable {
    var fullName: String
    /// `yyyy-MM-dd`, which the backend validates by pattern.
    var dob: String
    var monthlyIncome: Int
    var shopAddress: String
    /// Ten digits, no country code.
    var mobile: String
}

// MARK: - Response

/// The complete next screen (§8.4).
struct TurnResponse: Decodable, Sendable, Equatable {
    let journeyId: UUID
    let version: Int

    /// The engine's step. A plain `String`, not an enum: an unknown step from a
    /// newer backend must render whatever card came with it rather than failing
    /// to decode the whole response.
    let step: String

    let status: Status
    let progress: Progress
    let language: Language
    let messages: [TurnMessage]
    let card: Card?
    let quickReplies: [QuickReply]

    /// Voice turns only: what the backend heard.
    let transcript: String?
    let detectedLanguage: Language?

    let locks: Locks
    let demoMode: Bool

    enum Status: String, Decodable, Sendable {
        case active, completed, needsHuman = "needs_human"
    }

    struct Progress: Decodable, Sendable, Equatable {
        let index: Int
        let total: Int
        let label: String
        let etaSeconds: Int
    }

    struct Locks: Decodable, Sendable, Equatable {
        /// Decided by the backend from the teach-back result, and re-checked
        /// there when the tap arrives. The UI only reflects it (§9).
        let acceptEnabled: Bool
        let reason: String?
    }
}

struct TurnMessage: Decodable, Sendable, Equatable, Identifiable {
    let id: String
    let role: Role
    let text: String
    /// Relative, e.g. `/api/audio/<key>.mp3`, so the same payload works on
    /// localhost and through the tunnel (phase 7).
    let audioUrl: String?

    enum Role: String, Decodable, Sendable {
        case assistant, user
    }
}

struct QuickReply: Decodable, Sendable, Equatable, Identifiable {
    let label: String
    let send: Send

    var id: String { label }

    /// What tapping the chip sends. The backend composes both halves, so a chip
    /// can never send an action the current step does not accept.
    struct Send: Decodable, Sendable, Equatable {
        let type: String
        let text: String?
        /// Decoded as a raw dictionary and re-encoded verbatim: the client has
        /// no reason to understand an action it is only relaying, and treating
        /// it as opaque means a new backend action needs no app release.
        let action: RawAction?
    }
}

/// An action the backend sent us to send back, kept as opaque JSON.
struct RawAction: Codable, Sendable, Equatable {
    let json: [String: JSONValue]

    init(from decoder: Decoder) throws {
        json = try [String: JSONValue](from: decoder)
    }

    func encode(to encoder: Encoder) throws {
        try json.encode(to: encoder)
    }
}

/// Minimal JSON value, so an opaque action can be relayed without modelling it.
enum JSONValue: Codable, Sendable, Equatable {
    case string(String)
    case number(Double)
    case bool(Bool)
    case object([String: JSONValue])
    case array([JSONValue])
    case null

    init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if container.decodeNil() {
            self = .null
        } else if let value = try? container.decode(Bool.self) {
            self = .bool(value)
        } else if let value = try? container.decode(Double.self) {
            self = .number(value)
        } else if let value = try? container.decode(String.self) {
            self = .string(value)
        } else if let value = try? container.decode([String: JSONValue].self) {
            self = .object(value)
        } else if let value = try? container.decode([JSONValue].self) {
            self = .array(value)
        } else {
            throw DecodingError.dataCorruptedError(
                in: container, debugDescription: "unsupported JSON value"
            )
        }
    }

    func encode(to encoder: Encoder) throws {
        var container = encoder.singleValueContainer()
        switch self {
        case .string(let value): try container.encode(value)
        case .number(let value): try container.encode(value)
        case .bool(let value): try container.encode(value)
        case .object(let value): try container.encode(value)
        case .array(let value): try container.encode(value)
        case .null: try container.encodeNil()
        }
    }
}

// MARK: - OTP

struct StartJourneyRequest: Encodable, Sendable {
    var product = "personal_loan"
    var language: Language?
}

struct OtpSendResponse: Decodable, Sendable, Equatable {
    let sent: Bool
    let expiresInSec: Int
    /// Dev only. Shown as an obvious fake-SMS banner, never as a real message.
    let demoCode: String?
}

struct OtpVerifyRequest: Encodable, Sendable {
    let code: String
}
